const $=s=>document.querySelector(s),money=n=>Math.round(n).toLocaleString('ru-RU')+' ₸',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data=QorModel.demo(),isDemo=true,plans=[];
try{const saved=JSON.parse(localStorage.getItem('qor-data'));if(saved){data=validate(saved);isDemo=false;}}catch(e){}
function groups(){return [...new Set(data.map(r=>r.product))].map(name=>({name,rows:data.filter(r=>r.product===name).sort((a,b)=>a.date.localeCompare(b.date))}));}
function nextDate(){const d=new Date(data.map(r=>r.date).sort().at(-1)+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10);}
function init(){const date=nextDate();$('#plan-date').value=date;$('#plan-date').min=date;$('#product-filter').innerHTML=groups().map(g=>`<option>${esc(g.name)}</option>`).join('');$('#source-label').textContent=isDemo?'Пример работы кафе':'Ваши данные · локально';$('#source-detail').textContent=isDemo?' · синтетическая история продаж':` · ${data.length} записей · сохранено в этом браузере`;render();}
function compute(){const buffer=Number($('#buffer').value)/100,factor=Number($('#scenario').value);return groups().map(g=>{const rows=g.rows,forecast=Math.round(QorModel.predict(rows,$('#plan-date').value)*factor),qty=Math.ceil(forecast*(1+buffer)),ordinary=Math.round(rows.slice(-7).reduce((s,r)=>s+r.prepared,0)/7),last=rows.at(-1);return {...g,forecast,qty,ordinary,cost:last.cost,saving:Math.max(0,(Math.max(0,ordinary-forecast)-Math.max(0,qty-forecast))*last.cost),metrics:QorModel.evaluate(rows)};});}
function table(list,full){return `<div class="table-wrap"><table><thead><tr><th>Продукт</th><th>Обычно, шт.</th><th>Прогноз спроса</th><th>План, шт.</th>${full?'<th>Разница к обычному</th>':''}<th>Потенциал / день</th></tr></thead><tbody>${list.map((p,i)=>`<tr><td><span class="product-icon">${['◒','◔','▱','◈'][i%4]}</span>${esc(p.name)}</td><td>${p.ordinary}</td><td>${p.forecast}</td><td><strong>${p.qty}</strong></td>${full?`<td>${p.qty-p.ordinary>0?'+':''}${p.qty-p.ordinary} шт.</td>`:''}<td><span class="tag">${money(p.saving)}</span></td></tr>`).join('')}</tbody></table></div>`;}
function render(){plans=compute();$('#buffer-value').textContent=$('#buffer').value+'%';$('#date-label').textContent=new Date($('#plan-date').value+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});$('#waste').textContent=money(plans.reduce((s,p)=>s+p.rows.slice(-7).reduce((v,r)=>v+(r.prepared-r.sold)*r.cost,0),0));$('#saving').textContent=money(plans.reduce((s,p)=>s+p.saving,0));const valid=plans.filter(p=>p.metrics.wape!==null),average=k=>valid.reduce((s,p)=>s+p.metrics[k],0)/Math.max(1,valid.length);$('#accuracy').textContent=valid.length?average('wape').toFixed(1)+'%':'Нет продаж';$('#baseline').textContent=valid.length?`Baseline: ${average('baseline').toFixed(1)}% · среднее WAPE по товарам`:'Недостаточно ненулевых продаж';$('#preview-table').innerHTML=table(plans.slice(0,4),false);$('#plan-table').innerHTML=table(plans,true);const best=[...plans].sort((a,b)=>b.saving-a.saving)[0];$('#insight-text').textContent=best.saving>0?`${best.name}: план ${best.qty} шт. вместо обычных ${best.ordinary}. Потенциально ${money(best.saving)} меньше списаний при выбранном спросе.`:'При выбранном сценарии сокращение списаний не ожидается. Проверьте резерв и риск нехватки товара.';$('#model-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Товар</th><th>Дней проверки</th><th>WAPE модели</th><th>WAPE baseline</th><th>Результат</th></tr></thead><tbody>${plans.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.metrics.n}</td><td>${p.metrics.wape===null?'—':p.metrics.wape.toFixed(1)+'%'}</td><td>${p.metrics.baseline===null?'—':p.metrics.baseline.toFixed(1)+'%'}</td><td>${p.metrics.wape===null?'Нет продаж':p.metrics.wape<p.metrics.baseline?'Модель лучше':'Baseline лучше — нужен пилот'}</td></tr>`).join('')}</tbody></table></div>`;chart();}
function chart(){const p=plans.find(p=>p.name===$('#product-filter').value)||plans[0],rows=p.rows.slice(-14),values=[...rows.map(r=>r.sold),p.forecast],max=Math.max(10,...values)*1.15,w=620,h=205,pad=30,bottom=172,step=(w-2*pad)/14;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Продажи товара за последние 14 дней и прогноз"><title>${esc(p.name)}: продажи и прогноз</title>`;for(let i=0;i<=3;i++){const y=bottom-i*45;svg+=`<line x1="30" y1="${y}" x2="610" y2="${y}" stroke="#edf0e9"/><text x="0" y="${y+3}" font-size="9" fill="#8e998f">${Math.round(max*i*45/140)}</text>`;}values.forEach((v,i)=>{const x=pad+i*step,barH=v/max*140;svg+=`<rect x="${x}" y="${bottom-barH}" width="21" height="${barH}" rx="4" fill="${i===14?'#a5cc88':'#387e60'}" opacity="${i===14?1:.5+i*.035}"><title>${i===14?'Прогноз':rows[i].date}: ${v} шт.</title></rect>`;if(i%3===0||i===14)svg+=`<text x="${x+10}" y="193" text-anchor="middle" font-size="9" fill="#89948b">${i===14?'План':rows[i].date.slice(8)+'.'+rows[i].date.slice(5,7)}</text>`;});$('#chart').innerHTML=svg+'</svg>';}
function go(page){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===page));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=document.querySelector(`[data-page="${page}"] span`).textContent;if(page==='history')renderHistory();window.scrollTo({top:0,behavior:'smooth'});location.hash=page;}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#buffer').oninput=render;$('#scenario').onchange=render;$('#plan-date').onchange=()=>{if(!$('#plan-date').value||$('#plan-date').value<nextDate()){$('#plan-date').value=nextDate();notify('Дата плана должна быть позже последней даты продаж.');}render();};$('#product-filter').onchange=chart;
function notify(s){$('#notice').textContent=s;setTimeout(()=>$('#notice').textContent='',5000);}
function download(name,rows){const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#sample').onclick=()=>download('qor-example.csv',[['date','product','sold','prepared','price','cost'],...QorModel.demo().map(r=>[r.date,r.product,r.sold,r.prepared,r.price,r.cost])]);$('#export').onclick=()=>download('qor-plan-'+$('#plan-date').value+'.csv',[['date','product','forecast','prepare','potential_saving_kzt'],...plans.map(p=>[$('#plan-date').value,p.name,p.forecast,p.qty,p.saving])]);$('#upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Максимальный размер CSV — 2 МБ.');const parsed=validate(parseCSV(await f.text()));try{localStorage.setItem('qor-data',JSON.stringify(parsed));}catch{notify('Данные загружены на эту сессию. Браузер не разрешил сохранение.');}data=parsed;isDemo=false;$('#import-error').textContent='';init();notify(`Загружено ${data.length} записей. Прогноз пересчитан.`);go('overview');}catch(err){$('#import-error').textContent=err.message;}e.target.value='';};init();
